import XCTest

final class FeedImgTapTests: XCTestCase {
    func testTapFirstFeedImage() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        sleep(2)

        var tapped = false
        let images = app.images.allElementsBoundByIndex
        for img in images {
            let f = img.frame
            if img.exists && img.isHittable && f.height > 150 && f.minY > 300 && f.minY < 900 {
                img.tap()
                tapped = true
                break
            }
        }
        if !tapped {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).tap()
        }
        sleep(3)
        let shot = XCTAttachment(screenshot: XCUIScreen.main.screenshot())
        shot.lifetime = .keepAlways
        add(shot)
    }
}

